import { defineChapterTopic, type ChapterAuthorSpec } from '../chapter-package-engine';
import type { EducationTopic } from '../education-types';
import type { VERIFIED_SOURCES } from '../verified-sources';

const RAD_DISCLAIMER =
  'Educational radiology and imaging orientation principles only (5 de-identified normal CC-licensed reference plates bundled; multi-slice DICOM & pathology series remain Asset Required). Never use for clinical diagnosis.';

const RAD_ASSET_GAP = {
  status: 'asset_required' as const,
  summary:
    'Physical imaging principles, axial/coronal/sagittal orientation conventions, 3D Explorer clipping planes, and 5 de-identified CC-licensed normal reference plates (Chest/Foot X-ray, Brain CT/MRI, Kidney US) are bundled. Full multi-slice DICOM and pathology imaging series across chapters N1–N14 remain Asset Required.',
  missingAssets: ['Multi-slice DICOM CT/MRI volumes and clinical pathology teaching stacks across all 14 radiology chapters (N1–N14)'],
};

interface RadMeta {
  modality: string;
  region: string;
  orientation: string;
  keyFindings: string;
}

function makeRadChapter(
  num: number,
  id: string,
  chapterTitle: string,
  title: string,
  summary: string,
  meta: RadMeta,
  extraReadKey: keyof typeof VERIFIED_SOURCES,
  comp: { colA: string; colB: string; rows: ChapterAuthorSpec['comparisonTable']['rows'] },
  mechanisms: string[],
  clinical: string,
  fmas: string[],
  sys: ChapterAuthorSpec['relatedSystems'],
  mcqs: ChapterAuthorSpec['selfChecks'],
): ChapterAuthorSpec {
  return {
    id,
    domainId: 'radiology_imaging',
    chapterCode: `N${num}`,
    chapterOrder: num,
    chapterTitle,
    title,
    summary,
    targetTracks: ['medical_foundations', 'clinical_applied', 'graduate_research'],
    curriculumMappings: [
      { frameworkId: 'pk_pmdc_mbbs', gradeOrYear: 'MBBS Years 1–5', unitOrModule: `Radiological Anatomy & Imaging Orientation (${chapterTitle})`, status: 'recommended' },
      { frameworkId: 'pk_uhs_mbbs', gradeOrYear: 'MBBS Years 1–5', unitOrModule: `Vertical Integration — Medical Imaging (${chapterTitle})`, status: 'institution_specific' },
      { frameworkId: 'hms_pathways', gradeOrYear: 'MD Years 1–2', unitOrModule: `Integrated Anatomy & Imaging Correlation (${chapterTitle})`, status: 'institution_specific' },
      { frameworkId: 'anat_soc_core', gradeOrYear: 'BS / Graduate', unitOrModule: `Cross-Sectional & Physical Imaging Principles (${chapterTitle})`, status: 'recommended' },
    ],
    prerequisites: ['Anatomical planes & directional terminology (Domain A1)', 'Cross-sectional organ relationships (Domain A)'],
    learningObjectives: [
      `Explain the physical signal-generation mechanism and radiation profile for ${meta.modality} in ${meta.region}.`,
      `Apply standard radiological viewing orientation (${meta.orientation}) and relate slices to 3D Explorer clipping planes.`,
      `Describe structured teaching expectations (${meta.keyFindings}) while recognising local DICOM/radiograph Asset Required status.`,
    ],
    depthExplanations: {
      medical_foundations: `Modality: ${meta.modality} | Region: ${meta.region} | Orientation Convention: ${meta.orientation}. ${mechanisms.join(' ')} Expected Teaching Findings: ${meta.keyFindings}. Use the 3D Explorer axial/coronal/sagittal clipping planes alongside external Radiopaedia and NLM MedPix archives because local diagnostic images remain Asset Required.`,
      clinical_applied: `Clinical imaging orientation in ${chapterTitle.toLowerCase()} balances spatial resolution, speed, contrast safety, and ALARA radiation stewardship: ${clinical}`,
      graduate_research: `Quantitative imaging science models photon attenuation (Beer–Lambert law, CT Hounsfield calibration), Bloch equation T1/T2 relaxation kinetics, acoustic impedance boundaries, and reconstruction kernels governing ${chapterTitle.toLowerCase()}.`,
    },
    keyConcepts: [
      { term: `Modality & Region (${meta.modality})`, definition: `${meta.modality} applied to ${meta.region}.` },
      { term: 'Orientation Convention', definition: meta.orientation },
      { term: 'Key Teaching Findings', definition: meta.keyFindings },
    ],
    keyFacts: [
      `Modality: ${meta.modality} · Anatomical Region: ${meta.region}.`,
      `Standard Orientation: ${meta.orientation}.`,
      'Local radiographs/DICOM series are NOT bundled (Asset Required); external Radiopaedia/MedPix links and 3D Explorer clipping planes provide safe anatomical orientation.',
    ],
    mechanisms,
    comparisonTable: { columnA: comp.colA, columnB: comp.colB, rows: comp.rows },
    misconceptions: [
      { misconception: 'On an axial CT or MRI slice, the left side of the image corresponds to the patient’s left side.', correction: 'Standard radiological axial convention views the body from the feet upward: the patient’s RIGHT side appears on the VIEWER’S LEFT, and anterior is at the top.' },
      { misconception: 'CT and MRI measure the same physical property and merely differ in cost.', correction: 'CT measures electron-density X-ray attenuation (Hounsfield Units, ionising radiation), whereas MRI measures hydrogen-proton magnetic relaxation (T1/T2/DWI, non-ionising).' },
    ],
    clinicalCorrelation: clinical,
    summaryParagraph: `${chapterTitle} connects imaging physics and ${meta.orientation.toLowerCase()} directly to 3D cross-sectional anatomy. External Radiopaedia and NLM MedPix datasets supply genuine clinical teaching images where local radiographs are marked Asset Required.`,
    keyTakeaways: [
      `${meta.modality} — ${meta.region}: ${meta.orientation}.`,
      `Key findings template: ${meta.keyFindings}.`,
      clinical,
    ],
    crossSubjectLinks: [
      { domainId: 'human_anatomy', relation: '3D Explorer axial, coronal, and sagittal clipping planes mirror multiplanar CT/MRI reconstruction.' },
      { domainId: 'pathology', relation: 'Tissue oedema, infarction, haemorrhage, and mass effect shift radiographic attenuation and MRI signal.' },
    ],
    relatedSystems: sys,
    relatedFmaConceptIds: fmas,
    visualFormats: ['medical_imaging', '3d_anatomy', '2d_diagram'],
    diagram: {
      id: `diag-n${num}`,
      title: `${chapterTitle} — Signal Physics → Orientation → Anatomical Mapping`,
      kind: 'pathway',
      caption: `Modality: ${meta.modality} | Region: ${meta.region} | Findings: ${meta.keyFindings}`,
      disclaimer: RAD_DISCLAIMER,
      nodes: [
        { id: 'n1', label: `Modality: ${meta.modality}`, sublabel: meta.region, tone: 'blue' },
        { id: 'n2', label: 'Orientation Convention', sublabel: meta.orientation, tone: 'teal' },
        { id: 'n3', label: 'Teaching Findings Schema', sublabel: meta.keyFindings, tone: 'amber' },
      ],
      links: [
        { from: 'n1', to: 'n2', label: 'Reconstruction onto standard anatomical planes' },
        { from: 'n2', to: 'n3', label: 'Compare external MedPix/Radiopaedia normal vs abnormal examples' },
      ],
    },
    assetDisclosure: RAD_ASSET_GAP,
    activity: {
      title: `3D Cross-Sectional Orientation & MedPix Check (${chapterTitle})`,
      kind: '3d_inspection',
      prompt: `Open the 3D Anatomy Explorer with clipping enabled in ${meta.region}, align the view to "${meta.orientation}", and review external Radiopaedia/MedPix teaching images alongside the expected findings: ${meta.keyFindings}.`,
      keyTakeaway: clinical,
    },
    readingKeys: ['radiopaedia_planes', 'medpix_nlm', extraReadKey],
    shortAnswers: [
      { id: `sa-n${num}-1`, prompt: `State the physical signal mechanism, radiation status, and spatial orientation convention for ${meta.modality} in ${meta.region}.`, expectedPoints: [`Modality: ${meta.modality}`, `Orientation: ${meta.orientation}`, mechanisms[0] ?? summary], modelAnswer: `${meta.modality} in ${meta.region}: ${meta.orientation}. ${mechanisms.join(' ')}`, level: 'medical_foundations' },
      { id: `sa-n${num}-2`, prompt: `Contrast ${comp.colA} versus ${comp.colB} using the structured imaging matrix.`, expectedPoints: comp.rows.map((r) => `${r.dimension}: ${r.primary} vs ${r.comparator}`), modelAnswer: comp.rows.map((r) => `${r.dimension}: ${r.primary} vs ${r.comparator} (${r.clinicalOrFunctionalNote}).`).join(' '), level: 'medical_foundations' },
      { id: `sa-n${num}-3`, prompt: `Explain how the expected findings (${meta.keyFindings}) translate into safe clinical decision-making.`, expectedPoints: [meta.keyFindings, clinical], modelAnswer: `${meta.keyFindings}. ${clinical}`, level: 'clinical_applied' },
    ],
    appliedCase: {
      id: `app-n${num}-1`,
      title: `Imaging Orientation Exercise: ${chapterTitle}`,
      scenario: `Modality: ${meta.modality}. Region: ${meta.region}. Viewing orientation: ${meta.orientation}. A teaching case (inspectable externally on MedPix/Radiopaedia) demonstrates: ${meta.keyFindings}.`,
      questions: ['Which anatomical landmarks verify correct patient laterality and plane orientation first?', 'Why was this modality chosen over alternatives regarding physics or radiation dose?'],
      workedSolution: `Orientation check: ${meta.orientation}. Findings correlate with ${meta.keyFindings}. Rationale: ${clinical}`,
      level: 'clinical_applied',
      disclaimer: RAD_DISCLAIMER,
    },
    selfChecks: mcqs,
    educationalDisclaimer: RAD_DISCLAIMER,
  };
}

